# GitHub's 4-core runner is slower than the hardware the 300 s budget was set on (H116);
# CI allows 600 s and records the measured total in memory-loop-ci-replay.json.
timeout 660s python3 scripts/check-memory-loop-timing.py --budget 600 --output .lake/memory-loop-ci-replay --results memory-loop-ci-replay.json \
  || { for f in .lake/memory-loop-ci-replay/*.log; do echo "== $f"; tail -20 "$f"; done; exit 1; }

export SOLKEY_ROOT="$RUNNER_TEMP/solidity-cli-solkey"
cp -a tests/migration/solkey "$SOLKEY_ROOT"
node --input-type=module <<'JS'
import {readFileSync, mkdirSync, writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
const root = process.env.SOLKEY_ROOT;
const gradle = readFileSync(join(root, 'keyext.solidity.core/build.gradle'), 'utf8');
const file = gradle.match(/ext\.soljsonFile\s*=\s*"([^"]+)"/)[1];
const sha = gradle.match(/ext\.soljsonSha256\s*=\s*"([0-9a-f]{64})"/)[1];
const response = await fetch(`https://raw.githubusercontent.com/ethereum/solc-bin/gh-pages/bin/${file}`);
if (!response.ok) throw new Error(`compiler download: HTTP ${response.status}`);
const data = Buffer.from(await response.arrayBuffer());
if (createHash('sha256').update(data).digest('hex') !== sha) throw new Error('compiler hash mismatch');
const dir = join(root, 'keyext.solidity.core/build/soljson');
mkdirSync(dir, {recursive:true});
writeFileSync(join(dir, file), data);
JS
